  globalThis.addEventListener('fetch', (event) => {
    const response = handle(event.request);
    if (response) {
      event.respondWith(response);
      if (appShell && event.request.mode === 'navigate') event.waitUntil(appShell.populate().catch(() => {}));
    }
  });
